#![doc = include_str ! ("../README.md")]
#![no_std]

const COMPRESSION_RATE: u32 = 32;
const CHUNK_CUTOFF: u32 = 6;
const N_SEGMENTS: usize = 8177;
const SEGMENT_OFFSET: u32 = 8;

#[inline(always)]
pub fn get_pow2_div_pow10_params(exp: i32) -> (usize, (u32, u32)) {
    debug_assert!(exp >= (COMPRESSION_RATE * SEGMENT_OFFSET) as i32);
    let segment_idx =
        (exp as u32 / COMPRESSION_RATE - SEGMENT_OFFSET) as usize;
    (segment_idx, POW2_DIV_POW10_PARAMS[segment_idx])
}

#[inline(always)]
pub fn lookup_pow2_div_pow10(
    segment_idx: usize,
    chunk_idx: usize,
) -> (u128, u128, u128) {
    debug_assert!(segment_idx < N_SEGMENTS);
    let offset = segment_idx * CHUNK_CUTOFF as usize;
    POW2_DIV_POW10_TABLE[offset + chunk_idx]
}

